def _normalize_child_runtime_tuple(
    *,
    model: str,
    provider: str,
    base_url: str,
    api_key: Any,
    api_mode: str,
    explicit_provider: bool,
    explicit_base_url: bool,
    acp_command: Optional[str] = None,
) -> tuple[str, str, Any, str]:
    """Keep a delegated child's provider/model/runtime tuple coherent."""
    provider = (provider or "").strip()
    model = (model or "").strip()
    base_url = (base_url or "").strip()
    api_key = api_key.strip() if isinstance(api_key, str) else api_key
    api_mode = (api_mode or "").strip()
    original_runtime = (provider, base_url, api_key, api_mode)

    if acp_command:
        return provider, base_url, api_key, api_mode

    try:
        from hermes_cli.models import detect_provider_for_model
        from hermes_cli.runtime_provider import resolve_runtime_provider
    except Exception:
        return provider, base_url, api_key, api_mode

    target_provider = provider
    if not explicit_provider:
        try:
            detected = detect_provider_for_model(model, provider)
        except Exception:
            detected = None
        if detected:
            target_provider = detected[0]

    if explicit_base_url:
        return target_provider, base_url, api_key, api_mode

    normalized_target = (target_provider or "").strip().lower()
    if normalized_target in {"custom", "copilot-acp"}:
        return target_provider, base_url, api_key, api_mode

    needs_runtime_refresh = normalized_target != (provider or "").strip().lower()
    if not needs_runtime_refresh:
        try:
            current_runtime = resolve_runtime_provider(
                requested=target_provider,
                target_model=model,
            ) or {}
        except Exception:
            current_runtime = {}
        current_base_url = str(current_runtime.get("base_url") or "").strip()
        current_api_mode = str(current_runtime.get("api_mode") or "").strip()
        if current_base_url and base_url and current_base_url != base_url:
            needs_runtime_refresh = True
        elif current_api_mode and api_mode and current_api_mode != api_mode:
            needs_runtime_refresh = True

    if not needs_runtime_refresh:
        return target_provider, base_url, api_key, api_mode

    try:
        runtime = resolve_runtime_provider(
            requested=target_provider,
            target_model=model,
        ) or {}
    except Exception:
        return original_runtime

    required_fields = {"provider", "base_url", "api_key", "api_mode"}
    if not required_fields.issubset(runtime):
        return original_runtime

    resolved_provider = str(runtime.get("provider") or "").strip()
    resolved_base_url = str(runtime.get("base_url") or "").strip()
    resolved_api_key = runtime.get("api_key")
    if isinstance(resolved_api_key, str):
        resolved_api_key = resolved_api_key.strip()
    resolved_api_mode = str(runtime.get("api_mode") or "").strip()
    if (
        not resolved_provider
        or resolved_provider.lower() != normalized_target
        or not resolved_base_url
        or not resolved_api_mode
    ):
        return original_runtime

    return (
        resolved_provider,
        resolved_base_url,
        resolved_api_key,
        resolved_api_mode,
    )


